import {userLibrary} from '@app/web-player/library/state/likes-store';
import {BackendResponse} from '@common/http/backend-response/backend-response';
import {apiClient, queryClient} from '@common/http/query-client';
import {showHttpErrorToast} from '@common/http/show-http-error-toast';
import {useMutation} from '@tanstack/react-query';
import {message} from '@ui/i18n/message';
import {toast} from '@ui/toast/toast';

interface Response extends BackendResponse {}

interface Payload {
  artistId: number;
}

export function useFollowArtist() {
  return useMutation({
    mutationFn: (payload: Payload) => followArtist(payload),
    onSuccess: (response, payload) => {
      toast(message('Following artist'));
      userLibrary().add([{id: payload.artistId, model_type: 'artist'} as any]);
      queryClient.invalidateQueries({queryKey: ['artists']});
    },
    onError: r => showHttpErrorToast(r),
  });
}

function followArtist(payload: Payload): Promise<Response> {
  return apiClient
    .post(`artists/${payload.artistId}/follow`)
    .then(r => r.data);
}
